{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_0",
      "quote": "In fact, evidence for a volume-­ outcome relationship has been accumulated for various medical interventions including surgeries, dialysis, perinatal as well as intensive care. 4-14 Based on these findings, minimum volume standards have been introduced in numerous countries, particularly for highly specialised surgical procedures. 15 16 Still, criticism remains. First, some studies have raised doubts about the underlying proposed volume-­ outcome relationship. 17 18 Furthermore, uniform international guidance for minimum volume standards is seldom established, resulting, for example, in different cut-­ off thresholds and different regulatory approaches across different countries. 15 Last, different effects of minimum volume standards have been discussed in the literature, including adverse effects such as an expansion of indications as well as a threat to emergency care.",
      "reason": "The text describes the current state of knowledge regarding the volume-outcome relationship and highlights uncertainties and criticisms regarding minimum volume standards."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_0",
      "quote": "Hence, despite the ongoing debate about the advantages and disadvantages of minimum volume standards, there has been no systematic review on the effects of minimum volume standards in hospitals. This systematic review aims to address this research gap.",
      "reason": "The authors explicitly state the need for the review by identifying a research gap: the lack of a systematic review on the effects of minimum volume standards in hospitals."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_0",
      "quote": "In Germany, a rapid review was published in 2012 by the Institute for Quality and Efficiency in Healthcare (IQWiG). In total, 10 studies were included in this report. The majority of them were before-­ after studies with only one time point of data collection before and one after the implementation of minimum volume standards. As two time points in total, however, do not allow for the calculation of time trends, the authors' conclusion was that 'all studies showed a design-­ related potential for bias as well as methodological shortcomings that limited the validity of the results'. 20-22",
      "reason": "The authors identify a previous rapid review and explain why the current systematic review is needed (the previous review had methodological shortcomings and did not allow for the calculation of time trends)."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This review evaluates the effects of minimum volume standards (a policy/regulatory intervention), not a specific clinical intervention with a proposed biological or psychological mechanism of action."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not utilize or present a logic model for the intervention."
    }
  ],
  "confidence": 100
}

